TDD in TypeScript, tests provided. Create an npm project with vitest and save this as test/sequtils.test.ts verbatim, then implement src/sequtils.ts so it passes unchanged:

import { expect, test } from 'vitest'
import { revcomp, transcribe, hamming } from '../src/sequtils'

test('revcomp', () => {
  expect(revcomp('AAAACCCGGT')).toBe('ACCGGGTTTT')
})

test('transcribe', () => {
  expect(transcribe('GATGGAACTTGACTACGTAAATT')).toBe('GAUGGAACUUGACUACGUAAAUU')
})

test('hamming', () => {
  expect(hamming('GAGCCTACTAACGGGAT', 'CATCGTAATGACGGCCT')).toBe(7)
  expect(() => hamming('A', 'AA')).toThrow()
})

Then extend with your own tests for revcomp input validation (reject 'ACGX') and hamming of identical strings being 0. `npm test` must pass; show the run.

