const DNA_COMPLEMENT: Record<string, string> = {
  A: 'T',
  T: 'A',
  G: 'C',
  C: 'G',
}

function validateDna(seq: string): void {
  for (const base of seq) {
    if (!(base in DNA_COMPLEMENT)) {
      throw new Error(`Invalid DNA base: ${base}`)
    }
  }
}

/** Reverse complement of a DNA string. Throws on invalid bases. */
export function revcomp(seq: string): string {
  validateDna(seq)
  let out = ''
  for (let i = seq.length - 1; i >= 0; i--) {
    out += DNA_COMPLEMENT[seq[i]]
  }
  return out
}

/** Transcribe DNA to RNA (replace T with U). Throws on invalid bases. */
export function transcribe(seq: string): string {
  validateDna(seq)
  return seq.replace(/T/g, 'U')
}

/** Hamming distance between two equal-length strings. Throws if lengths differ. */
export function hamming(a: string, b: string): number {
  if (a.length !== b.length) {
    throw new Error('Strings must have equal length')
  }
  let dist = 0
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) dist++
  }
  return dist
}

